  expect(
    overlaps({ from: "2026-03-13", to: "2026-03-15" }, { from: "2026-03-10", to: "2026-03-13" }),
  ).toBe(true);
});

test("an unreturned loan clashes with a range that starts on its due date", () => {
  const db = new Database(":memory:");
  db.run("CREATE TABLE loans (id TEXT, item_id TEXT, out_date TEXT, due_date TEXT, returned_date TEXT)");
  db.run("CREATE TABLE reservations (id TEXT, item_id TEXT, from_date TEXT, to_date TEXT)");
  db.run("INSERT INTO loans VALUES ('L-101', 'drill-01', '2026-03-06', '2026-03-13', NULL)");
  const found = clashes(db, "drill-01", { from: "2026-03-13", to: "2026-03-15" });
  expect(found).toEqual(["L-101"]);
});

